let seed=42;function rand(){seed=(seed*1664525+1013904223)%4294967296;return seed/4294967296}function pick(a){return a[Math.floor(rand()*a.length)]}function lognormal(base,spread){return Math.round(base*Math.exp((rand()-.5)*spread))}
function buildData(){const rows=[],ugcTypes=TYPES.filter(v=>v!=='官方或原始内容'),typeBoost={'官方或原始内容':.94,'配音改编':1.18,'混剪/鬼畜':1.08,'表情包/梗图':1.12,'AI生成':1.24},ipBoost=[1.16,1.01,1.09],monthBoost=[.86,.94,1.04,1.15,1.08],rankBoost=[1.22,1.06,.93];let n=0;function add(ip,ii,month,mi,source,type,rank,purpose){n++;const official=source==='官方',views=lognormal(185000*typeBoost[type]*ipBoost[ii]*monthBoost[mi]*rankBoost[rank-1]*(official?.96:1.08),.72);let likeRate=(official?.058:.075)+({'官方或原始内容':0,'配音改编':.010,'混剪/鬼畜':.006,'表情包/梗图':.016,'AI生成':.008}[type]||0),coreRate=(official?.011:.016)+({'官方或原始内容':0,'配音改编':.005,'混剪/鬼畜':.004,'表情包/梗图':.007,'AI生成':.003}[type]||0);likeRate*=.88+rand()*.24;coreRate*=.84+rand()*.32;const likes=Math.round(views*likeRate),coins=Math.round(views*coreRate*(.28+rand()*.10)),favorites=Math.round(views*coreRate*(.62+rand()*.10)),comments=Math.round(views*(.004+rand()*.008));rows.push({id:`r${n}`,purpose,rank,ip:ip.name,ipKey:ip.key,color:ip.color,month,source,type,title:pick(TITLES[ip.key]),views,likes,coins,favorites,comments})}IPS.forEach((ip,ii)=>MONTHS.forEach((month,mi)=>{for(let rank=1;rank<=3;rank++){add(ip,ii,month,mi,'官方','官方或原始内容',rank,'来源对比');add(ip,ii,month,mi,'用户二创',ugcTypes[(ii+mi+rank)%ugcTypes.length],rank,'来源对比')}ugcTypes.forEach(type=>{for(let rank=1;rank<=3;rank++)add(ip,ii,month,mi,'用户二创',type,rank,'类型分析')})}));return rows.map(d=>({...d,engagement:(d.coins+d.favorites)/d.views,likeRate:d.likes/d.views}))}
