let linkedHistory=[];
function stateSnapshot(){return {ip:state.ip,source:state.source,type:state.type,month:state.month}}
function applyLinkedFilter(next){linkedHistory.push(stateSnapshot());Object.assign(state,next);state.brushIds=null;typeSelect.value=state.type;monthSelect.value=state.month;applyDataTheme(state.ip);syncChips();update()}
