function syncLinkState(){const bar=document.querySelector('#linkState');if(!bar)return;const parts=[];if(state.ip!=='全部')parts.push(state.ip);if(state.source!=='全部')parts.push(state.source);if(state.type!=='全部')parts.push(state.type);if(state.month!=='全部')parts.push(state.month.replace('2026-','')+'月');const count=filtered().length;bar.querySelector('strong').textContent=parts.length?`${parts.join(' × ')} · ${count}条分析记录`:`全部${DATA.length}条分析记录`;bar.classList.remove('flash');requestAnimationFrame(()=>bar.classList.add('flash'))}
function initLinkedUI(){document.querySelectorAll('[data-jump]').forEach(btn=>btn.onclick=()=>document.querySelector(btn.dataset.jump)?.scrollIntoView({behavior:'smooth',block:'start'}));const clearLink=document.querySelector('#clearLink');if(clearLink)clearLink.onclick=clearLinkedState;document.querySelectorAll('[data-clear-chart]').forEach(btn=>btn.onclick=clearLinkedState);const clearType=document.querySelector('#clearType');if(clearType)clearType.onclick=()=>applyLinkedFilter({ip:state.ip,source:'全部',type:'全部'});const undoLink=document.querySelector('#undoLink');if(undoLink)undoLink.onclick=()=>{const prev=linkedHistory.pop();if(!prev)return;Object.assign(state,prev);state.brushIds=null;typeSelect.value=state.type;monthSelect.value=state.month;applyDataTheme(state.ip);syncChips();update()}}
function update(){const sourceRows=filtered('来源对比'),typeRows=filtered('类型分析');document.querySelector('#dataZone').classList.remove('data-refresh');const clearType=document.querySelector('#clearType');if(clearType)clearType.hidden=state.type==='全部'&&state.source==='全部';renderMetrics(sourceRows);renderSourceGap();renderSourceBoxplot();renderTypeShare();renderTypeMatrix();renderScatter(typeRows);renderTypeLollipop();renderTypeComposition();renderInsights(sourceRows,typeRows);renderSourceTrend();syncLinkState();requestAnimationFrame(animateDashboard)}
