function renderInsights(sourceRows,typeRows){const lead=document.querySelector('#insightLead'),list=document.querySelector('#insightList'),note=document.querySelector('#hypothesisText'),rate=a=>d3.sum(a,x=>x.coins+x.favorites)/(d3.sum(a,x=>x.views)||1),official=sourceRows.filter(x=>x.source==='官方'),ugc=sourceRows.filter(x=>x.source==='用户二创'),or=rate(official),ur=rate(ugc),officialMedian=d3.median(official,x=>x.views)||0,ugcMedian=d3.median(ugc,x=>x.views)||0,typeStats=d3.rollups(typeRows,v=>({rate:rate(v),views:d3.median(v,x=>x.views)||0,count:v.length}),x=>x.type).sort((a,b)=>b[1].rate-a[1].rate),bestType=typeStats[0],monthStats=d3.rollups(sourceRows,v=>({views:d3.mean(v,x=>x.views)||0,count:v.length}),x=>x.month).sort((a,b)=>b[1].views-a[1].views),bestMonth=monthStats[0],scope=state.ip==='全部'?'三个IP':state.ip;if(!sourceRows.length&&!typeRows.length){lead.textContent='当前筛选下没有分析记录。';list.innerHTML='';note.textContent='请返回全部类型或月份后再查看。';return}lead.innerHTML=official.length&&ugc.length?`${scope}在最近五个月里，官方头部内容的播放中位数为 <strong>${fmt(officialMedian)}</strong>，二创头部内容为 <strong>${fmt(ugcMedian)}</strong>。这反映了热潮之后，二创内容仍在持续传播。`:`当前筛选包含 <strong>${sourceRows.length+typeRows.length}</strong> 条近期分析记录，反映了该范围内的二创活跃度。`;list.innerHTML=`<div class="insight-item"><span>近期对比范围</span><strong>官方 ${official.length} 条，二创 ${ugc.length} 条</strong></div><div class="insight-item"><span>二创余热是否明显</span><strong>${official.length&&ugc.length?(ugcMedian>=officialMedian?'二创头部仍高于官方':'官方头部暂时高于二创'):'当前筛选中的内容保持近期传播'}</strong></div><div class="insight-item"><span>最能维持互动的玩法</span><strong>${bestType?`${bestType[0]}，核心互动率 ${pct(bestType[1].rate)}（n=${bestType[1].count}）`:'当前筛选聚焦官方内容'}</strong></div><div class="insight-item"><span>近期播放高点</span><strong>${bestMonth?`${bestMonth[0].slice(5)}月，平均播放 ${fmt(bestMonth[1].views)}（n=${bestMonth[1].count}）`:'当前范围呈现整体近期表现'}</strong></div>`;note.textContent=`2026年5—9月的数据反映了三个IP在热潮之后的二创活跃度、传播持续性和有效玩法。当前共${sourceRows.length}条来源比较记录、${typeRows.length}条类型分析记录。`}
